<template>
  <section class="linked-polls">
    <div class="poll-heading"><div><span class="kicker">TEAM DECISIONS</span><h4>Plan it together</h4></div><button type="button" class="outline-button" :disabled="!event.id || busy" @click="composing = !composing">{{ composing ? 'Cancel poll' : '+ Create a vote' }}</button></div>
    <p class="hint">Create one or more votes for this event: choose a date, pick a venue or settle the menu. Each vote appears on the private event page for invited people.</p>
    <p v-if="!event.id" class="save-note">Save the event first, then add votes. You can save with the date still to be decided.</p>
    <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="notice" role="status" class="notice">{{ notice }}</p>
    <form v-if="composing && event.id" class="poll-compose" @submit.prevent="save">
      <label>Question<input v-model.trim="draft.question" required maxlength="255" placeholder="Which date works best for our anniversary?" /></label>
      <label v-for="(_, index) in draft.options" :key="index" class="answer-row">Answer {{ index + 1 }}<span><input v-model.trim="draft.options[index]" required maxlength="64" placeholder="Date or other option" /><button v-if="draft.options.length > 2" type="button" @click="draft.options.splice(index,1)">Remove</button></span></label>
      <button type="button" class="text-button" :disabled="draft.options.length >= 12" @click="draft.options.push('')">+ Add answer</button>
      <div class="poll-grid"><label>Voting closes ({{ event.timezone || 'your timezone' }})<input v-model="draft.closesAt" type="datetime-local" required /></label><label>Notify invited people<select v-model="draft.deliveryMode"><option value="internal">In-app</option><option value="both">In-app &amp; eligible text</option><option value="sms">Eligible text &amp; email fallback</option></select></label></div>
      <label class="check-label"><input v-model="draft.shareResults" type="checkbox" /> Share results when voting closes</label>
      <button type="submit" class="primary-button" :disabled="busy">{{ busy ? 'Saving…' : 'Save vote' }}</button><small class="hint">Saving adds the vote. Use Send vote below when you are ready to notify invitees.</small>
    </form>
    <div v-for="poll in polls" :key="poll.id" class="poll-card"><div><strong>{{ poll.votingConfig?.question || poll.title }}</strong><p>{{ poll.votingClosedAt ? 'Voting closed' : `Closes ${dateLabel(poll.votingConfig?.closesAt || poll.endsAt)}` }} · {{ poll.votingConfig?.options?.length || 0 }} choices</p></div><div class="poll-actions"><button type="button" :disabled="busy || !!poll.votingClosedAt" @click="send(poll)">Send vote</button><button type="button" @click="reviewing = poll">Results &amp; settings</button></div></div>
    <p v-if="event.id && !polls.length && !composing" class="hint">No votes yet. RSVP stays separate from the decisions you want people to vote on.</p>
    <StaffPollResultsReview v-if="reviewing" :agency-id="agencyId" :event="reviewing" @close="reviewing = null; load()" @changed="load" />
  </section>
</template>
<script setup>
import { ref, watch } from 'vue';
import api from '../../services/api';
import StaffPollResultsReview from './StaffPollResultsReview.vue';
import { isoToZonedDatetimeLocal, zonedDatetimeLocalToIso } from '../../utils/timezones';
const props = defineProps({ agencyId: { type: Number, required:true }, event: {type:Object,required:true}, userIds: {type:Array,default:()=>[]} });
const pollTimezone = () => props.event.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
const localInput = value => isoToZonedDatetimeLocal(new Date(value).toISOString(),pollTimezone());
const blank = () => ({question:'',options:['',''],closesAt:localInput(Date.now()+7*86400000),deliveryMode:'internal',shareResults:true});
const polls=ref([]), composing=ref(false), busy=ref(false), error=ref(''), notice=ref(''), reviewing=ref(null), draft=ref(blank());
let generation=0;
const base=()=>`/agencies/${props.agencyId}/company-events`;
const dateLabel=value=>value?new Date(value).toLocaleString():'not set';
async function load(){ const current=++generation; if(!props.event.id){polls.value=[];return;} try{const {data}=await api.get(base(),{params:{communicationsOnly:1}});if(current===generation)polls.value=(Array.isArray(data)?data:[]).filter(p=>Number(p.votingConfig?.linkedEventId)===Number(props.event.id));}catch{if(current===generation)error.value='Could not load this event’s votes.';} }
async function save(){ if(busy.value)return; if(!props.userIds.length){error.value='Add invited people before creating a vote.';return;} busy.value=true;error.value='';notice.value='';const current=generation;try{const deadline=new Date(zonedDatetimeLocalToIso(draft.value.closesAt,pollTimezone()));if(!Number.isFinite(deadline.getTime())||deadline<=new Date())throw new Error('Choose a voting deadline in the future.');await api.post(base(),{title:`${props.event.title} · ${draft.value.question}`.slice(0,255),description:props.event.description||'',eventType:'team_poll',startsAt:new Date().toISOString(),endsAt:deadline.toISOString(),timezone:props.event.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',audience:{userIds:props.userIds,groupIds:[],roleKeys:[]},invitedAgencyIds:props.event.invitedAgencyIds||[],rsvpMode:'custom_vote',votingConfig:{enabled:true,viaSms:draft.value.deliveryMode!=='internal',deliveryMode:draft.value.deliveryMode,question:draft.value.question,options:draft.value.options.map((label,i)=>({key:String(i+1),label})),linkedEventId:Number(props.event.id),closesAt:deadline.toISOString(),shareResults:draft.value.shareResults,resultsVisibility:'after_close',allowOther:false},reminderConfig:{enabled:false,anchor:'poll_close',offsetsHours:[24,2],channels:{inApp:true,sms:false}}});if(current!==generation)return;composing.value=false;draft.value=blank();notice.value='Vote created and linked to this event. Choose Send vote to notify the invited people.';await load();}catch(e){error.value=e.response?.data?.error?.message||e.message||'Could not create the vote.';}finally{busy.value=false;} }
async function send(poll){if(!window.confirm(`Send “${poll.votingConfig?.question || poll.title}” to its invited people?`))return;busy.value=true;error.value='';try{const {data}=await api.post(`${base()}/${poll.id}/send-poll`,{unsentOnly:true});notice.value=`Vote invitations: ${data.inAppCount||0} in-app, ${data.sentCount||0} texts, ${data.emailCount||0} emails. Delivery history shows any skipped recipients.`;}catch(e){error.value=e.response?.data?.error?.message||'Could not send vote invitations.';}finally{busy.value=false;} }
watch(()=>[props.agencyId,props.event.id],()=>{composing.value=false;draft.value=blank();error.value='';notice.value='';load();},{immediate:true});
</script>
<style scoped>
.linked-polls{padding:0;color:#26483d}.poll-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.kicker{font-size:12px;font-weight:750;letter-spacing:.14em;color:#5d7467}h4{font-size:18px;margin:7px 0}.hint{font-size:14px;line-height:1.65;color:#627269}.outline-button,.poll-actions button,.answer-row button{border:1px solid #cfdcd4;border-radius:8px;padding:9px 12px;background:#fff;color:#35624e;cursor:pointer;font:inherit;font-size:14px;white-space:nowrap}.save-note,.notice{padding:12px;border-radius:10px;background:#edf4ec;font-size:14px;line-height:1.6}.error{color:#a53e2f;font-size:13px}.poll-compose{margin-top:18px;padding:20px;border:1px solid #d9e3db;border-radius:12px;background:#f8faf7;display:grid;gap:14px}.poll-compose label{display:grid;gap:7px;font-size:14px;font-weight:650}.poll-compose input:not([type=checkbox]),.poll-compose select{padding:11px;border-radius:8px;border:1px solid #cddbd2;background:#fff;width:100%;box-sizing:border-box;color:#315141;font:inherit}.answer-row>span{display:flex;gap:8px}.poll-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.text-button{border:0;background:none;color:#356c51;text-align:left;cursor:pointer}.check-label{display:flex!important;align-items:center}.check-label input{accent-color:#2b7055}.primary-button{background:#245b46;border:0;border-radius:8px;color:white;padding:12px 18px;font:inherit;font-size:13px;cursor:pointer;justify-self:start}.poll-card{display:flex;justify-content:space-between;align-items:center;gap:12px;border:1px solid #dce5de;border-radius:12px;padding:16px;margin-top:12px}.poll-card strong{font-size:13px}.poll-card p{font-size:13px;color:#65736a;margin:7px 0 0}.poll-actions{display:flex;gap:6px;flex-wrap:wrap}button:disabled{opacity:.5;cursor:default}@media(max-width:650px){.poll-grid{grid-template-columns:1fr}.poll-card{align-items:flex-start;flex-direction:column}}
</style>
